249 |     if (params && Object.keys(params).length > 0) {
250 |       const searchParams = new URLSearchParams();
251 |       Object.entries(params).forEach(([key, value]) => {
252 |         if (value !== undefined) {
253 |           searchParams.append(key, String(value));
254 |         }
