292 | 
293 |       if (contentType?.includes('application/json')) {
294 |         error = await response.json();
295 |       } else {
296 |         error = {
297 |           success: false,
298 |           error: {
299 |             code: `HTTP_${response.status}`,
300 |             message: response.statusText || 'An error occurred',
301 |           },
302 |         };
303 |       }
304 | 
305 |       // 调用错误回调
306 |       if (this.onError) {
307 |         this.onError(error);
308 |       }
309 | 
310 |       throw new ApiRequestError(
311 |         response.status,
312 |         error.error.code,
313 |         error.error.message,
314 |         error.error.details
315 |       );
316 |     }
317 | 
318 |     if (contentType?.includes('application/json')) {
319 |       const result: ApiResponse<T> = await response.json();
320 |       return result.data;
321 |     }
322 | 
323 |     // 对于非JSON响应（如文件下载等）
324 |     return (await response.blob()) as unknown as T;
325 |   }
