333 |     }
334 | 
335 |     if (error instanceof Error) {
336 |       if (error.name === 'AbortError') {
337 |         return new TimeoutError('Request timeout');
338 |       }
339 | 
340 |       if (
341 |         error.message.includes('fetch') ||
342 |         error.message.includes('network')
343 |       ) {
