21 | export const useAgents = (
22 |   params: AgentsParams = {},
23 |   customOptions?: Omit<
24 |     UseQueryOptions<Awaited<ReturnType<typeof getAgents>>, Error, Awaited<ReturnType<typeof getAgents>>, ReturnType<typeof agentKeys.list>>,
25 |     'queryKey' | 'queryFn' | 'placeholderData'
26 |   >,
27 | ) => {
28 |   const queryClient = useQueryClient();
29 |   
30 |   // Normalize params: always include defaults unless explicitly overridden
31 |   // This ensures all queries use consistent parameters and share cache
32 |   const normalizedParams = useMemo(() => {
33 |     // Start with defaults
34 |     const normalized: AgentsParams = {
35 |       limit: DEFAULT_AGENT_PARAMS.limit,
36 |       sort_by: DEFAULT_AGENT_PARAMS.sort_by,
37 |       sort_order: DEFAULT_AGENT_PARAMS.sort_order,
38 |     };
39 |     
40 |     // Override with provided params
41 |     if (params.limit !== undefined) normalized.limit = params.limit;
42 |     if (params.sort_by !== undefined) normalized.sort_by = params.sort_by;
43 |     if (params.sort_order !== undefined) normalized.sort_order = params.sort_order;
44 |     
45 |     // Only include page if it's explicitly set AND > 1 (page 1 is default)
46 |     if (params.page !== undefined && params.page > 1) {
47 |       normalized.page = params.page;
48 |     }
49 |     
50 |     // Include search/filter params if provided
51 |     if (params.search) normalized.search = params.search;
52 |     if (params.has_default !== undefined) normalized.has_default = params.has_default;
53 |     if (params.has_mcp_tools !== undefined) normalized.has_mcp_tools = params.has_mcp_tools;
54 |     if (params.has_agentpress_tools !== undefined) normalized.has_agentpress_tools = params.has_agentpress_tools;
55 |     if (params.tools) normalized.tools = params.tools;
56 |     if (params.content_type !== undefined) normalized.content_type = params.content_type;
57 |     
58 |     return normalized;
59 |   }, [params]);
60 |   
61 |   // Get placeholder data from any existing agent list query in cache
62 |   // This allows us to reuse cached data from other queries with different params
63 |   const placeholderData = useMemo(() => {
64 |     // Check if we already have data for this exact query
65 |     const exactMatch = queryClient.getQueryData<Awaited<ReturnType<typeof getAgents>>>(
66 |       agentKeys.list(normalizedParams)
67 |     );
68 |     if (exactMatch) return exactMatch;
69 |     
70 |     // Try to find any cached agent list query
71 |     const allAgentQueries = queryClient.getQueriesData<Awaited<ReturnType<typeof getAgents>>>({ 
72 |       queryKey: agentKeys.lists() 
73 |     });
74 |     
75 |     // Find the most complete cached query (prefer ones with more agents)
76 |     let bestMatch: Awaited<ReturnType<typeof getAgents>> | undefined;
77 |     let maxAgents = 0;
78 |     
79 |     for (const [_, data] of allAgentQueries) {
80 |       if (data?.agents && data.agents.length > maxAgents) {
81 |         maxAgents = data.agents.length;
82 |         bestMatch = data;
83 |       }
84 |     }
85 |     
86 |     // If we have cached data and the params don't include search/filters,
87 |     // we can use the cached data as placeholder to show data immediately
88 |     const hasSearchOrFilters = normalizedParams.search || 
89 |                                normalizedParams.has_default !== undefined || 
90 |                                normalizedParams.has_mcp_tools !== undefined || 
91 |                                normalizedParams.has_agentpress_tools !== undefined ||
92 |                                normalizedParams.tools || 
