95 |     // Only use placeholder if we don't have search/filters that would change results
96 |     // and if we're not requesting a specific page (since pagination changes results)
97 |     const isPaginated = normalizedParams.page !== undefined && normalizedParams.page > 1;
98 |     
99 |     if (bestMatch && !hasSearchOrFilters && !isPaginated) {
100 |       return bestMatch;
101 |     }
102 |     
103 |     return undefined;
104 |   }, [queryClient, normalizedParams]);
105 |   
106 |   return useQuery({
107 |     queryKey: agentKeys.list(normalizedParams),
108 |     queryFn: () => getAgents(normalizedParams),
109 |     staleTime: 5 * 60 * 1000,
