import { z } from 'zod';

export const AgentSchema = z.object({
  id: z.string(),
  name: z.string(),
  model: z.string(),
  tools: z.array(z.string()),
});

export type Agent = z.infer<typeof AgentSchema>;

// API中使用
export const parseAgentResponse = (data: unknown): Agent => {
  return AgentSchema.parse(data);
};
```

